package com.citacloud.app.views;

import com.citacloud.app.models.*; import com.citacloud.app.security.*; import com.citacloud.app.services.InventarioService; import com.citacloud.app.util.FormatoMonto; import com.citacloud.app.views.components.PaginadorTabla;
import com.vaadin.flow.component.Component; import com.vaadin.flow.component.ClickEvent; import com.vaadin.flow.component.button.*; import com.vaadin.flow.component.checkbox.Checkbox; import com.vaadin.flow.component.combobox.ComboBox; import com.vaadin.flow.component.dialog.Dialog; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.icon.VaadinIcon; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.component.tabs.*; import com.vaadin.flow.component.textfield.*; import com.vaadin.flow.data.renderer.ComponentRenderer; import com.vaadin.flow.data.value.ValueChangeMode; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.math.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;

@Route(value="inventario",layout=MainLayout.class) @PageTitle("Inventario | CitaCloud") @PermitAll
public class InventarioView extends VerticalLayout {
 private final InventarioService service; private final UUID empresa; private final Grid<InventarioService.ProductoFila> grid=new Grid<>(InventarioService.ProductoFila.class,false); private final PaginadorTabla<InventarioService.ProductoFila> pager=new PaginadorTabla<>(grid); private final TextField buscar=new TextField(); private final ComboBox<CategoriaInventario> categoria=new ComboBox<>(); private final ComboBox<String> estado=new ComboBox<>(); private final ComboBox<Sucursal> sucursal=new ComboBox<>(); private String modo="INVENTARIO"; private boolean filtrosCargados;
 public InventarioView(InventarioService service){this.service=service;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();setWidthFull();setPadding(true);setSpacing(true);pager.setFilasPorPagina(10); construir(); cargar();}
 private void construir(){Button nuevo=botonPrincipal(VaadinIcon.PLUS,"Nuevo producto",e->formProducto(null));nuevo.getStyle().set("background-color","#16a34a");Button unidad=botonPrincipal(VaadinIcon.PACKAGE,"Nueva unidad",e->formUnidad());Button nuevaCategoria=botonPrincipal(VaadinIcon.TAGS,"Nueva categoría",e->formCategoria());Button movimientos=botonPrincipal(VaadinIcon.LIST,"Movimientos",e->mostrarMovimientos());movimientos.getStyle().set("background-color","#64748b");Button limpiar=botonPrincipal(VaadinIcon.ERASER,"Limpiar filtros",e->limpiarFiltros());limpiar.getStyle().set("background-color","#e2e8f0").set("color","#334155");HorizontalLayout acciones=new HorizontalLayout(nuevo,unidad,nuevaCategoria,movimientos,limpiar);acciones.setSpacing(false);acciones.getStyle().set("gap",".3rem");HorizontalLayout encabezado=new HorizontalLayout(new Div(new H2("Inventario"),new Paragraph("Controla medicamentos, materiales e insumos de la clínica.")),acciones);encabezado.setWidthFull();encabezado.setAlignItems(Alignment.CENTER);encabezado.setJustifyContentMode(JustifyContentMode.BETWEEN);add(encabezado,indicadores());
  buscar.setLabel("Buscar");buscar.setPlaceholder("Código, producto o código de barras");buscar.setValueChangeMode(ValueChangeMode.LAZY);buscar.addValueChangeListener(e->cargar());categoria.setLabel("Categoría");categoria.setItemLabelGenerator(CategoriaInventario::getNombre);categoria.addValueChangeListener(e->cargar());estado.setLabel("Estado");estado.setItems("Todos","Disponible","Bajo stock","Agotado","Activo","Inactivo");estado.setValue("Todos");estado.addValueChangeListener(e->cargar());sucursal.setLabel("Sucursal");sucursal.setItemLabelGenerator(Sucursal::getNombre);sucursal.addValueChangeListener(e->cargar());HorizontalLayout filtros=new HorizontalLayout(buscar,categoria,estado,sucursal);filtros.setWidthFull();filtros.setFlexGrow(2,buscar);add(filtros);configurarGrid();add(grid,pager);}
 private Component indicadores(){HorizontalLayout cajas=new HorizontalLayout();cajas.setWidthFull();cajas.setSpacing(true);InventarioService.Resumen r=empresa==null?new InventarioService.Resumen(0,0,0,0):service.resumen(empresa,null);cajas.add(tarjeta("PRODUCTOS",r.productos(),"#2563eb"),tarjeta("BAJO STOCK",r.bajoStock(),"#d97706"),tarjeta("AGOTADOS",r.agotados(),"#dc2626"),tarjeta("POR VENCER",r.porVencer(),"#7c3aed"));return cajas;}
 private Div tarjeta(String titulo,long valor,String color){Span etiqueta=new Span(titulo);etiqueta.getStyle().set("font-size","1rem").set("font-weight","600").set("color","#cbd5e1");H2 cantidad=new H2(String.valueOf(valor));cantidad.getStyle().set("margin",".45rem 0 0").set("font-size","1.9rem").set("color","#f8fafc");Div d=new Div(etiqueta,cantidad);d.setWidthFull();d.getStyle().set("flex","1 1 220px").set("box-sizing","border-box").set("background","#18233a").set("border-radius","10px").set("padding","1.15rem 1.35rem").set("min-width","190px");return d;}
 private void configurarGrid(){grid.addColumn(x->x.producto().getCodigo()).setHeader("CÓDIGO");grid.addColumn(x->x.producto().getNombre()).setHeader("PRODUCTO").setFlexGrow(1);grid.addColumn(x->x.producto().getCategoria().getNombre()).setHeader("CATEGORÍA");grid.addColumn(x->num(x.stock())).setHeader("STOCK");grid.addColumn(x->num(x.producto().getStockMinimo())).setHeader("MÍNIMO");grid.addColumn(new ComponentRenderer<>(x->badge(x.estado()))).setHeader("ESTADO");grid.addComponentColumn(x->menuAcciones(x.producto())).setHeader("ACCIONES");grid.setWidthFull();grid.setAllRowsVisible(true);}
 private void cargar(){if(empresa==null)return;if(!filtrosCargados){categoria.setItems(service.categorias(empresa));sucursal.setItems(service.sucursales(empresa));filtrosCargados=true;}if("MOVIMIENTOS".equals(modo)){mostrarMovimientos();return;}String q=buscar.getValue()==null?"":buscar.getValue().toLowerCase();pager.setItems(service.listar(empresa,sucursal.getValue()==null?null:sucursal.getValue().getId()).stream().filter(x->q.isBlank()||x.producto().getCodigo().toLowerCase().contains(q)||x.producto().getNombre().toLowerCase().contains(q)||(x.producto().getCodigoBarras()!=null&&x.producto().getCodigoBarras().toLowerCase().contains(q))).filter(x->categoria.getValue()==null||x.producto().getCategoria().getId().equals(categoria.getValue().getId())).filter(this::filtroEstado).filter(x->!"BAJO".equals(modo)||"BAJO STOCK".equals(x.estado())).toList());}
 private boolean filtroEstado(InventarioService.ProductoFila x){String e=estado.getValue();return "Todos".equals(e)||("Disponible".equals(e)&&"DISPONIBLE".equals(x.estado()))||("Bajo stock".equals(e)&&"BAJO STOCK".equals(x.estado()))||("Agotado".equals(e)&&"AGOTADO".equals(x.estado()))||("Activo".equals(e)&&x.producto().isActivo())||("Inactivo".equals(e)&&!x.producto().isActivo());}
 private void limpiarFiltros(){buscar.clear();categoria.clear();sucursal.clear();estado.setValue("Todos");modo="INVENTARIO";cargar();}
 private void mostrarMovimientos(){Dialog d=new Dialog();d.setHeaderTitle("Movimientos de inventario");d.setWidth("min(1100px,96vw)");Grid<MovimientoInventario> g=new Grid<>(MovimientoInventario.class,false);g.addColumn(x->x.getCreadoEn().format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"))).setHeader("FECHA");g.addColumn(MovimientoInventario::getNumero).setHeader("MOVIMIENTO");g.addColumn(MovimientoInventario::getTipo).setHeader("TIPO");g.addColumn(x->num(x.getCantidad())).setHeader("CANTIDAD");g.addColumn(x->x.getProducto().getNombre()).setHeader("PRODUCTO");TextField buscarMovimiento=new TextField("Buscar");buscarMovimiento.setPlaceholder("Número o producto");buscarMovimiento.setValueChangeMode(ValueChangeMode.LAZY);ComboBox<String> tipoMovimiento=new ComboBox<>("Tipo");tipoMovimiento.setItems("Todos","ENTRADA","SALIDA","AJUSTE");tipoMovimiento.setValue("Todos");PaginadorTabla<MovimientoInventario> paginador=new PaginadorTabla<>(g);paginador.setFilasPorPagina(5);Runnable cargarMovimientos=()->{String texto=buscarMovimiento.getValue()==null?"":buscarMovimiento.getValue().toLowerCase();String tipo=tipoMovimiento.getValue();paginador.setItems(service.movimientos(empresa).stream().filter(m->texto.isBlank()||m.getNumero().toLowerCase().contains(texto)||m.getProducto().getNombre().toLowerCase().contains(texto)).filter(m->"Todos".equals(tipo)||tipo.equals(m.getTipo())).toList());};buscarMovimiento.addValueChangeListener(e->cargarMovimientos.run());tipoMovimiento.addValueChangeListener(e->cargarMovimientos.run());HorizontalLayout filtros=new HorizontalLayout(buscarMovimiento,tipoMovimiento);filtros.setWidthFull();g.setWidthFull();g.setAllRowsVisible(true);cargarMovimientos.run();d.add(filtros,g,paginador);d.getFooter().add(botonCancelar(d));d.open();modo="INVENTARIO";}
private void formProducto(ProductoInventario p){Dialog d=new Dialog();d.setHeaderTitle(p==null?"Nuevo producto":"Editar producto");d.setWidth("min(760px,96vw)");TextField nombre=new TextField("Nombre *",p==null?"":p.getNombre());TextField barras=new TextField("Código de barras",p==null?"":p.getCodigoBarras());ComboBox<CategoriaInventario> cat=new ComboBox<>("Categoría *");cat.setItems(service.categorias(empresa));cat.setItemLabelGenerator(CategoriaInventario::getNombre);cat.setClearButtonVisible(true);cat.setValue(p==null?null:p.getCategoria());ComboBox<UnidadInventario> uni=new ComboBox<>("Unidad *");uni.setItems(service.unidades(empresa));uni.setItemLabelGenerator(UnidadInventario::getNombre);uni.setClearButtonVisible(true);uni.setValue(p==null?null:p.getUnidad());TextArea desc=new TextArea("Descripción",p==null?"":p.getDescripcion());TextField minimo=new TextField("Stock mínimo *",p==null?"0.00":num(p.getStockMinimo()));minimo.addBlurListener(e->formatear(minimo));Checkbox vence=new Checkbox("Controlar vencimiento",p!=null&&p.isControlaVencimiento());Checkbox facturable=new Checkbox("Disponible para facturación",p!=null&&p.isEsFacturable());TextField precioVenta=new TextField("Precio de venta (RD$) *",p==null||p.getPrecioVenta()==null?"":num(p.getPrecioVenta()));precioVenta.setPlaceholder("0.00");precioVenta.setEnabled(facturable.getValue());precioVenta.addBlurListener(e->formatear(precioVenta));facturable.addValueChangeListener(e->{precioVenta.setEnabled(e.getValue());if(!e.getValue())precioVenta.clear();});Checkbox activo=new Checkbox("Activo",p==null||p.isActivo());com.vaadin.flow.component.formlayout.FormLayout f=new com.vaadin.flow.component.formlayout.FormLayout(nombre,barras,cat,uni,desc,minimo,vence,facturable,precioVenta,activo);f.setResponsiveSteps(new com.vaadin.flow.component.formlayout.FormLayout.ResponsiveStep("0",1),new com.vaadin.flow.component.formlayout.FormLayout.ResponsiveStep("560px",2));f.setColspan(desc,2);Button guardar=botonGuardar("Guardar nuevo producto",e->{try{if(cat.getValue()==null||uni.getValue()==null)throw new IllegalArgumentException("Categoría y unidad son obligatorias.");service.guardar(empresa,p==null?null:p.getId(),nombre.getValue(),null,barras.getValue(),cat.getValue().getId(),uni.getValue().getId(),desc.getValue(),stockMinimo(minimo.getValue()),vence.getValue(),activo.getValue(),facturable.getValue(),facturable.getValue()?stockMinimo(precioVenta.getValue()):null);d.close();cargar();Notification.show("Producto guardado correctamente.");}catch(Exception ex){Notification.show(ex.getMessage()==null?"No se pudo guardar el producto.":ex.getMessage());}});d.add(f);d.getFooter().add(guardar,botonCancelar(d));d.open();}
 private void detalle(ProductoInventario p){Dialog d=new Dialog();d.setWidth("min(1100px,96vw)");d.setHeight("min(850px,92vh)");InventarioService.ProductoFila fila=service.listar(empresa,null).stream().filter(x->x.producto().getId().equals(p.getId())).findFirst().orElseThrow();HorizontalLayout titulo=new HorizontalLayout(new Div(new H2(p.getNombre().toUpperCase()),new Span(p.getCodigo()),badge(p.isActivo()?"ACTIVO":"INACTIVO")));titulo.setWidthFull();HorizontalLayout resumen=new HorizontalLayout(cardDetalle("STOCK ACTUAL",num(fila.stock())),cardDetalle("STOCK MÍNIMO",num(p.getStockMinimo())),cardDetalle("ESTADO STOCK",fila.estado()));resumen.setWidthFull();resumen.getStyle().set("flex-wrap","wrap");com.vaadin.flow.component.formlayout.FormLayout info=new com.vaadin.flow.component.formlayout.FormLayout(dato("Código",p.getCodigo()),dato("Categoría",p.getCategoria().getNombre()),dato("Unidad",p.getUnidad().getNombre()),dato("Código de barras",p.getCodigoBarras()),dato("Control vencimiento",p.isControlaVencimiento()?"Sí":"No"),dato("Estado",p.isActivo()?"Activo":"Inactivo"),dato("Descripción",p.getDescripcion()));info.setResponsiveSteps(new com.vaadin.flow.component.formlayout.FormLayout.ResponsiveStep("0",1),new com.vaadin.flow.component.formlayout.FormLayout.ResponsiveStep("760px",3));Tab ex=new Tab("Existencias"),mov=new Tab("Movimientos");Tabs tabs=p.isControlaVencimiento()?new Tabs(ex,new Tab("Lotes"),mov):new Tabs(ex,mov);Div cuerpo=new Div();cuerpo.setWidthFull();cuerpo.getStyle().set("padding-bottom","2rem");tabs.addSelectedChangeListener(e->pintarDetalle(cuerpo,p,e.getSelectedTab().getLabel()));pintarDetalle(cuerpo,p,"Existencias");d.add(titulo,resumen,new H4("INFORMACIÓN"),info,tabs,cuerpo);d.getFooter().add(botonCancelar(d));d.open();}
 private Component cardDetalle(String etiqueta,String valor){Div d=new Div(new Span(etiqueta),new H3(valor));d.getStyle().set("flex","1 1 160px").set("padding",".8rem 1rem").set("background","var(--lumo-contrast-5pct)").set("border-radius","10px");return d;} private Component dato(String etiqueta,String valor){return new Div(new Span(etiqueta),new Paragraph(valor==null||valor.isBlank()?"—":valor));} private void pintarDetalle(Div cuerpo,ProductoInventario p,String tab){cuerpo.removeAll();if("Existencias".equals(tab)){Grid<ExistenciaInventario> g=new Grid<>(ExistenciaInventario.class,false);g.addColumn(x->x.getSucursal().getNombre()).setHeader("SUCURSAL");g.addColumn(x->num(x.getCantidad())).setHeader("STOCK");g.addColumn(x->num(p.getStockMinimo())).setHeader("MÍNIMO");g.addComponentColumn(x->badge(x.getCantidad().signum()==0?"AGOTADO":x.getCantidad().compareTo(p.getStockMinimo())<=0?"BAJO STOCK":"DISPONIBLE")).setHeader("ESTADO");g.setAllRowsVisible(true);PaginadorTabla<ExistenciaInventario> pag=new PaginadorTabla<>(g);pag.setFilasPorPagina(5);pag.setItems(service.existenciasProducto(empresa,p.getId()));cuerpo.add(g,pag);return;}if("Lotes".equals(tab)){Grid<LoteInventario> g=new Grid<>(LoteInventario.class,false);g.addColumn(LoteInventario::getNumeroLote).setHeader("LOTE");g.addColumn(x->x.getFechaVencimiento()==null?"—":x.getFechaVencimiento().format(DateTimeFormatter.ofPattern("dd/MM/yyyy"))).setHeader("VENCIMIENTO");g.addColumn(x->num(x.getCantidad())).setHeader("CANTIDAD");g.setAllRowsVisible(true);PaginadorTabla<LoteInventario> pag=new PaginadorTabla<>(g);pag.setFilasPorPagina(5);pag.setItems(service.lotes(empresa,p.getId()));cuerpo.add(g,pag);return;}Grid<MovimientoInventario> g=new Grid<>(MovimientoInventario.class,false);g.addColumn(x->x.getCreadoEn().format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"))).setHeader("FECHA");g.addColumn(MovimientoInventario::getNumero).setHeader("MOVIMIENTO");g.addColumn(MovimientoInventario::getTipo).setHeader("TIPO");g.addColumn(x->num(x.getCantidad())).setHeader("CANTIDAD");g.addColumn(x->x.getSucursal().getNombre()).setHeader("SUCURSAL");g.setAllRowsVisible(true);PaginadorTabla<MovimientoInventario> pag=new PaginadorTabla<>(g);pag.setFilasPorPagina(5);pag.setItems(service.movimientos(empresa).stream().filter(x->x.getProducto().getId().equals(p.getId())).toList());cuerpo.add(g,pag);}
 private void formMovimiento(ProductoInventario p,String tipo){Dialog d=new Dialog();d.setHeaderTitle("Registrar "+tipo.toLowerCase());d.setWidth("min(1000px,96vw)");ComboBox<Sucursal> suc=new ComboBox<>("Sucursal *");suc.setItems(service.sucursales(empresa));suc.setItemLabelGenerator(Sucursal::getNombre);TextField motivo=new TextField("Motivo *");TextField cantidad=new TextField("Cantidad *");cantidad.addBlurListener(e->formatear(cantidad));TextField lote=new TextField("Lote");com.vaadin.flow.component.datepicker.DatePicker vence=new com.vaadin.flow.component.datepicker.DatePicker("Fecha de vencimiento");TextField costo=new TextField("Costo unitario");TextField referencia=new TextField("Referencia");TextArea observacion=new TextArea("Observación");com.vaadin.flow.component.formlayout.FormLayout f=new com.vaadin.flow.component.formlayout.FormLayout(suc,motivo,cantidad,lote,vence,costo,referencia,observacion);f.setResponsiveSteps(new com.vaadin.flow.component.formlayout.FormLayout.ResponsiveStep("0",1),new com.vaadin.flow.component.formlayout.FormLayout.ResponsiveStep("760px",3));f.setColspan(observacion,3);Button guardar=botonGuardar("Guardar movimiento",e->{try{if(suc.getValue()==null||motivo.getValue()==null||motivo.getValue().isBlank())throw new IllegalArgumentException("Sucursal y motivo son obligatorios.");service.registrarMovimiento(empresa,new InventarioService.MovimientoSolicitud(p.getId(),suc.getValue().getId(),tipo,motivo.getValue(),FormatoMonto.parse(cantidad.getValue()),null,lote.getValue(),vence.getValue(),costo.getValue().isBlank()?null:FormatoMonto.parse(costo.getValue()),referencia.getValue(),observacion.getValue()));d.close();cargar();Notification.show("Movimiento registrado correctamente.");}catch(Exception ex){Notification.show(ex.getMessage());}});d.add(f);d.getFooter().add(guardar,botonCancelar(d));d.open();}
 private Component menuAcciones(ProductoInventario producto){Button boton=icono(VaadinIcon.ELLIPSIS_DOTS_V,"Más acciones",e->{});com.vaadin.flow.component.contextmenu.ContextMenu menu=new com.vaadin.flow.component.contextmenu.ContextMenu(boton);menu.setOpenOnClick(true);menu.addItem("Ver producto",e->detalle(producto));menu.addItem("Editar producto",e->formProducto(producto));menu.addItem("Registrar entrada",e->formMovimiento(producto,"ENTRADA"));menu.addItem("Registrar salida",e->formMovimiento(producto,"SALIDA"));return boton;} private void formCategoria(){Dialog d=new Dialog();d.setHeaderTitle("Nueva categoría");TextField nombre=new TextField("Nombre *");Button guardar=botonGuardar("Guardar categoría",e->{try{service.crearCategoria(empresa,nombre.getValue());d.close();cargar();Notification.show("Categoría creada correctamente.");}catch(Exception x){Notification.show(x.getMessage());}});d.add(nombre);d.getFooter().add(guardar,botonCancelar(d));d.open();} private void formUnidad(){Dialog d=new Dialog();d.setHeaderTitle("Nueva unidad");TextField nombre=new TextField("Nombre *"),abreviatura=new TextField("Abreviatura");Button guardar=botonGuardar("Guardar unidad",e->{try{service.crearUnidad(empresa,nombre.getValue(),abreviatura.getValue());d.close();cargar();Notification.show("Unidad creada correctamente.");}catch(Exception x){Notification.show(x.getMessage());}});d.add(new com.vaadin.flow.component.formlayout.FormLayout(nombre,abreviatura));d.getFooter().add(guardar,botonCancelar(d));d.open();} private Button botonPrincipal(VaadinIcon icono,String tooltip,com.vaadin.flow.component.ComponentEventListener<ClickEvent<Button>> accion){Button b=new Button(icono.create(),accion);b.setTooltipText(tooltip);b.addThemeVariants(ButtonVariant.LUMO_PRIMARY);b.getStyle().set("min-width","48px").set("height","48px").set("background-color","#2563eb").set("color","#ffffff");return b;} private Button botonGuardar(String tooltip,com.vaadin.flow.component.ComponentEventListener<ClickEvent<Button>> accion){Button b=new Button(VaadinIcon.DISC.create(),accion);b.setTooltipText(tooltip);b.addThemeVariants(ButtonVariant.LUMO_PRIMARY);b.getStyle().set("min-width","48px").set("height","48px").set("background-color","#16a34a").set("color","#ffffff");return b;} private Button botonCancelar(Dialog dialog){Button b=new Button(VaadinIcon.CLOSE.create(),e->dialog.close());b.setTooltipText("Cancelar");b.getStyle().set("min-width","48px").set("height","48px").set("background-color","#e2e8f0").set("color","#1e293b");return b;} private Button icono(VaadinIcon i,String tooltip,com.vaadin.flow.component.ComponentEventListener<ClickEvent<Button>> listener){Button b=new Button(i.create(),listener);b.setTooltipText(tooltip);b.addThemeVariants(ButtonVariant.LUMO_TERTIARY_INLINE);return b;} private Span badge(String estado){Span s=new Span(estado);s.getStyle().set("font-weight","600").set("font-size",".75rem").set("color",estado.equals("AGOTADO")?"#b91c1c":estado.equals("BAJO STOCK")?"#b45309":"#15803d");return s;} private String num(BigDecimal n){return FormatoMonto.format(n==null?BigDecimal.ZERO:n);} private BigDecimal stockMinimo(String valor){if(valor==null||valor.isBlank())throw new IllegalArgumentException("El stock mínimo es obligatorio.");try{return FormatoMonto.parse(valor);}catch(NumberFormatException e){throw new IllegalArgumentException("El stock mínimo debe ser un número válido.");}} private void formatear(TextField f){try{if(!f.getValue().isBlank())f.setValue(num(FormatoMonto.parse(f.getValue())));}catch(Exception ignored){}}
}
